'use strict';
// Guardrail regression suite. Source: AAP 2022 KAS 3–9, 10, 16–17 and Figure 7.
// All thresholds used below are clinician-entered illustrative values, never generated by Kramer.
const assert=require('node:assert/strict');
const fs=require('node:fs');
const e=require('../assets/kramer-bili-core-v01041.js');
const base={ga:'40',age:'48',method:'TSB',unit:'mgdl',riskReviewed:true,
 thresholdChecked:true,discharge:'before72',zone:2};
let x=e.evaluate({...base,bili:'10'});
assert.equal(x.ready,true);
assert.equal(x.stats.biliMg,10);
assert.equal(x.thresholdReady,true);
assert.equal(x.stats.deltaPhoto,undefined,'Must not invent phototherapy threshold');
x=e.evaluate({...base,bili:'12',photo:'17.1',exchange:'24'});
assert.equal(x.stats.deltaPhoto,5.1);
assert.match(x.stats.followup,/1–2 días/);
assert.equal(x.stats.escalation,22);
assert.equal(x.urgency,'revalorar');
assert.equal(e.followup(1.9,23,'before72').includes('4–8 h'),true);
assert.match(e.followup(2.5,26,'before72'),/4–24 h/);
assert.match(e.followup(4,26,'before72'),/1–2 días/);
assert.match(e.followup(7,60,'before72'),/≤3 días/);
assert.match(e.followup(7,80,'after72'),/juicio clínico/);
x=e.evaluate({...base,age:'24',bili:'12',photo:'13.3',exchange:'21.4'});
assert.equal(x.stats.deltaPhoto,1.3,'External AAP 40wk 24h phototherapy test vector');
assert.equal(x.stats.escalation,19.4);
x=e.evaluate({...base,ga:'35',age:'24',bili:'8',photo:'10.6',exchange:'17.9'});
assert.equal(x.stats.deltaPhoto,2.6,'External AAP 35wk 24h test vector');
assert.equal(x.stats.escalation,15.9);
assert.match(x.notes.join('|'),/EG <38 semanas ya está contemplada/);
assert.equal(x.extraRisk,false,'Gestation alone must NOT cause risk curve');
x=e.evaluate({...base,hemolysis:true,bili:'10'});
assert.equal(x.extraRisk,true);
assert.match(x.curve,/factores adicionales/);
x=e.evaluate({...base,riskReviewed:false,photo:'13.3',bili:'12'});
assert.equal(x.thresholdReady,false);
assert.equal(x.stats.deltaPhoto,undefined,'Unknown risk category must fail closed');
x=e.evaluate({...base,thresholdChecked:false,photo:'13.3',bili:'12'});
assert.equal(x.stats.deltaPhoto,undefined,'Unverified table values must fail closed');
x=e.evaluate({...base,ga:'34',age:'24',photo:'13',bili:'12'});
assert.equal(x.ready,false);
assert.equal(x.thresholdReady,false,'Never apply 35+ thresholds to 34wk infant');
x=e.evaluate({...base,age:'337',photo:'13',bili:'12'});
assert.equal(x.thresholdReady,false,'No extrapolation beyond 336h');
x=e.evaluate({...base,bili:'12',direct:'13'});
assert.equal(x.ready,false,'Direct > total is invalid');
x=e.evaluate({...base,bili:'12',direct:'1.1'});
assert.equal(x.stats.directPct,9.17);
assert.ok(x.alerts.some(s=>s.includes('colestasis')));
x=e.evaluate({...base,bili:'16',method:'TcB',photo:'17.1'});
assert.ok(x.alerts.some(s=>s.includes('≥15')));
assert.ok(x.alerts.some(s=>s.includes('≤3 mg/dL')));
assert.ok(!x.alerts.some(s=>s.includes('TSB ≥umbral')));
x=e.evaluate({...base,bili:'19',photo:'17.1',exchange:'24'});
assert.ok(x.alerts.some(s=>s.includes('TSB ≥umbral')));
x=e.evaluate({...base,bili:'22.1',photo:'17.1',exchange:'24'});
assert.ok(x.alerts.some(s=>s.includes('escalamiento')));
x=e.evaluate({...base,bili:'24.1',photo:'17.1',exchange:'24'});
assert.ok(x.alerts.some(s=>s.includes('exanguinotransfusión')));
x=e.evaluate({...base,bili:'12',prior:'6',priorAge:'18',priorMethod:'TSB'});
assert.equal(x.stats.rate,0.2);
assert.ok(x.alerts.some(s=>s.includes('Velocidad de ascenso')));
x=e.evaluate({...base,age:'24',bili:'12',prior:'6',priorAge:'4',priorMethod:'TSB'});
assert.equal(x.stats.rate,0.3);
assert.ok(x.alerts.some(s=>s.includes('hemólisis')));
x=e.evaluate({...base,age:'48',bili:'12',prior:'9',priorAge:'36',priorMethod:'TcB'});
assert.equal(x.stats.rate,undefined,'Do not compare distinct measurement modalities');
x=e.evaluate({...base,age:'48',bili:'12',prior:'9',priorAge:'50',priorMethod:'TSB'});
assert.equal(x.ready,false);
x=e.evaluate({...base,bili:'12',birthWeight:'3200',currentWeight:'2800'});
assert.equal(x.stats.lossPct,12.5);
assert.ok(x.alerts.some(s=>s.includes('Pérdida ponderal')));
x=e.evaluate({...base,bili:'205.248',unit:'umol',photo:'292.4784',exchange:'410.496'});
assert.equal(x.stats.biliMg,12);
assert.equal(x.stats.deltaPhoto,5.1);
assert.equal(e.ageFromDates('2026-11-01T03:00','2026-11-02T15:00'),36);
assert.equal(e.ageFromDates('2026-11-02T15:00','2026-11-01T03:00'),null);
assert.equal(e.peditoolsUrl({...base,bili:'12'}).includes('ga=40&age=48&risk=none&bili=12'),true);
assert.equal(e.peditoolsUrl({...base,hemolysis:true,method:'TcB',bili:'16'}).includes('risk=any&tcb=16'),true);
const html=fs.readFileSync('pediatria-evaluacion-rapida.html','utf8');
const sw=fs.readFileSync('sw.js','utf8');
const css=fs.readFileSync('assets/pediatria-rapid-v01039.css','utf8');
assert.match(html,/id="kbili-output"/);
assert.match(html,/data-kbili="riskReviewed"/);
assert.match(html,/data-kbili="thresholdChecked"/);
assert.match(html,/kramer-bili-core-v01041\.js/);
assert.match(html,/kramer-bili-ui-v01041\.js/);
assert.match(sw,/kramer-bili-core-v01041\.js/);
assert.match(sw,/kramer-bili-ui-v01041\.js/);
assert.match(css,/\.kbili-metrics/);
const oldCore=fs.readFileSync('assets/pediatria-rapid-core.js','utf8');
assert.doesNotMatch(oldCore,/thresholdData|kramer-bili/,'Legacy pediatric clinical engine left untouched');
const currentCore=fs.readFileSync('assets/kramer-bili-core-v01041.js','utf8');
assert.doesNotMatch(currentCore,/\bfetch\s*\(|\bXMLHttpRequest\b|localStorage|sessionStorage|navigator\.sendBeacon/);
console.log('Kramer clinical support PASS: thresholds fail closed, AAP examples, trend, TSB/TcB, hemolysis, direct bilirubin, escalation, follow-up, privacy and offline.');
